from __future__ import annotations

from typing import Literal

from models import UserProfile

FieldName = Literal["email", "display_name"]

_PRIMARY: dict[str, UserProfile] = {}
_REPLICA: dict[str, UserProfile] = {}


def seed_user(profile: UserProfile) -> None:
    _PRIMARY[profile.user_id] = profile
    _REPLICA[profile.user_id] = profile


def bootstrap_user(profile: UserProfile) -> None:
    seed_user(profile)


def write_primary(user_id: str, profile: UserProfile) -> None:
    _PRIMARY[user_id] = profile


def write_replica(user_id: str, profile: UserProfile) -> None:
    _REPLICA[user_id] = profile


def read_primary(user_id: str) -> UserProfile | None:
    return _PRIMARY.get(user_id)


def read_replica(user_id: str) -> UserProfile | None:
    return _REPLICA.get(user_id)


def replicate_user(user_id: str) -> None:
    """Simulate replication catch-up for one user."""
    if user_id in _PRIMARY:
        _REPLICA[user_id] = _PRIMARY[user_id]


def replicate_all() -> int:
    count = 0
    for uid, prof in list(_PRIMARY.items()):
        _REPLICA[uid] = prof
        count += 1
    return count


def reset_stores() -> None:
    _PRIMARY.clear()
    _REPLICA.clear()


def pick_field(profile: UserProfile | None, field: FieldName) -> str | None:
    if profile is None:
        return None
    if field == "email":
        return profile.email
    return profile.display_name


